-- 1. 检查 HMS 后端 MySQL 分区表规模与索引
SELECT COUNT(*) FROM PARTITIONS;              -- 超 5000w 需要警惕
SHOW INDEX FROM PARTITIONS;                    -- 必须有 (TBL_ID, PART_NAME)
SHOW INDEX FROM PARTITION_KEY_VALS;

-- 2. 开启 direct SQL，绕过 DataNucleus ORM
SET hive.metastore.try.direct.sql=true;
SET hive.metastore.try.direct.sql.ddl=true;

-- 3. 验证分区裁剪是否下推
EXPLAIN EXTENDED
SELECT user_id FROM ods.user_event
WHERE dt='2026-06-13' AND hour='10';
-- 看是否出现 'Partition Filter Operator'，以及读到的 partition 数

-- 4. 更新列统计（必须带 FOR COLUMNS，否则只更新表级 numRows）
ANALYZE TABLE ods.user_event PARTITION(dt='2026-06-13')
  COMPUTE STATISTICS FOR COLUMNS user_id, event_type;

-- 5. 验证统计信息是否写入
DESCRIBE FORMATTED ods.user_event PARTITION(dt='2026-06-13');
-- 看 numRows, rawDataSize, numFiles

-- 6. 修复绕过 HMS 写入的分区
MSCK REPAIR TABLE ods.user_event SYNC PARTITIONS;
